'use client'
import { useState } from 'react'
import { supabase } from '@/lib/supabase'

const LOGO = 'data:image/png;base64,'

export default function InsolesPage() {
  const [form, setForm] = useState({ name: '', phone: '', complaint: '' })
  const [submitted, setSubmitted] = useState(false)
  const [saving, setSaving] = useState(false)

  const set = (f: string, v: string) => setForm(p => ({ ...p, [f]: v }))

  async function submit() {
    if (!form.name || !form.phone) { alert('יש למלא שם וטלפון'); return }
    setSaving(true)
    await supabase.from('patients').insert([{
      first_name: form.name.split(' ')[0],
      last_name: form.name.split(' ').slice(1).join(' ') || '',
      phone: form.phone,
      status: 'lead',
      notes: `ליד מדרסים\nתלונה: ${form.complaint}`,
      diagnosis: 'מדרסים אורטופדיים',
    }])
    const msg = encodeURIComponent(`👟 ליד חדש — מדרסים!\n\nשם: ${form.name}\nטלפון: ${form.phone}\nתלונה: ${form.complaint}`)
    setTimeout(() => window.open(`https://wa.me/972545953889?text=${msg}`, '_blank'), 500)
    setSaving(false)
    setSubmitted(true)
  }

  return (
    <div style={{ fontFamily: 'Heebo, sans-serif', direction: 'rtl', background: '#f8fafc', minHeight: '100vh' }}>

      {/* Header */}
      <div style={{ background: 'linear-gradient(135deg, #1a3a5c 0%, #0d2240 100%)', padding: '0', position: 'relative', overflow: 'hidden' }}>
        <div style={{ padding: '16px 24px', display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
          <a href="https://www.yoav-avni-clinic.com" style={{ textDecoration: 'none' }}>
            <img src={LOGO} style={{ height: '60px', objectFit: 'contain' }} alt="קליניקת יואב אבני" />
          </a>
          <a href="https://www.yoav-avni-clinic.com" style={{ color: 'rgba(255,255,255,0.7)', fontSize: '13px', textDecoration: 'none' }}>← חזור לאתר</a>
        </div>

        <div style={{ padding: '50px 24px 80px', textAlign: 'center', maxWidth: '700px', margin: '0 auto' }}>
          <div style={{ display: 'inline-block', background: 'rgba(62,184,229,0.15)', border: '1px solid rgba(62,184,229,0.3)', borderRadius: '20px', padding: '6px 16px', marginBottom: '20px' }}>
            <span style={{ fontSize: '12px', fontWeight: '700', color: '#3eb8e5', textTransform: 'uppercase', letterSpacing: '0.08em' }}>מדרסים אורטופדיים בהתאמה אישית | קליניקת יואב אבני PT</span>
          </div>
          <h1 style={{ fontSize: '40px', fontWeight: '900', color: '#fff', lineHeight: '1.2', marginBottom: '16px', letterSpacing: '-1px' }}>
            מדרס בהתאמה אישית<br/>
            <span style={{ color: '#3eb8e5' }}>שמותאם בדיוק לרגל שלך.</span>
          </h1>
          <p style={{ fontSize: '17px', color: 'rgba(255,255,255,0.8)', lineHeight: '1.7', marginBottom: '32px', maxWidth: '560px', margin: '0 auto 32px' }}>
            סריקה דיגיטלית עם <strong style={{ color: '#3eb8e5' }}>Albert Pressure</strong> — 5,184 חיישנים שמנתחים את כפות הרגליים שלך. בליווי יואב אבני, פיזיותרפיסט מוסמך. לא מדרס מהמדף — מדרס שבנוי בדיוק בשבילך.
          </p>
          <a href="#form" style={{ display: 'inline-block', padding: '16px 36px', background: '#3eb8e5', color: '#fff', borderRadius: '12px', fontSize: '16px', fontWeight: '800', textDecoration: 'none', boxShadow: '0 8px 24px rgba(62,184,229,0.4)' }}>
            לתיאום סריקה ←
          </a>
          <div style={{ marginTop: '16px', fontSize: '13px', color: 'rgba(255,255,255,0.6)' }}>
            ✅ החזרים מקופות חולים וביטוח פרטי &nbsp;|&nbsp; ✅ בפניית רופא
          </div>
        </div>

        <svg viewBox="0 0 1440 60" style={{ display: 'block', marginBottom: '-2px' }}>
          <path d="M0,60 C360,0 1080,60 1440,20 L1440,60 Z" fill="#f8fafc" />
        </svg>
      </div>

      {/* מה זה מדרס בהתאמה אישית */}
      <div style={{ padding: '60px 24px 20px', maxWidth: '860px', margin: '0 auto', textAlign: 'center' }}>
        <h2 style={{ fontSize: '28px', fontWeight: '800', color: '#1a3a5c', marginBottom: '12px' }}>מה זה בעצם מדרס בהתאמה אישית?</h2>
        <p style={{ fontSize: '15px', color: '#64748b', marginBottom: '36px', lineHeight: '1.8', maxWidth: '680px', margin: '0 auto 36px' }}>
          מדרס מותאם אישית הוא תומך לכף הרגל שנבנה על בסיס הנתונים הייחודיים של <strong>הרגל שלך</strong> — לא גודל, לא קשת כללית — אלא מיפוי מדויק של נקודות הלחץ, צורת הקשת, ומרכז הכובד שלך בהליכה. התוצאה: מדרס שפותר את הבעיה, לא מסתיר אותה.
        </p>
        <div style={{ display: 'grid', gridTemplateColumns: 'repeat(3,1fr)', gap: '16px' }}>
          {[
            { icon: '📡', title: '5,184 חיישנים', text: 'סורק Albert Pressure מודד כל נקודת לחץ בדיוק מלא — גם בעמידה וגם בהליכה' },
            { icon: '🏥', title: 'פיזיותרפיסט בתהליך', text: 'יואב אבני PT מלווה כל סריקה — מוסיף בדיקה קלינית שלא ניתן לקבל בחנות' },
            { icon: '💳', title: 'החזרים מקופ"ח', text: 'ניתן לקבל החזר מקופת החולים ומביטוח פרטי בהצגת פניית רופא' },
          ].map(f => (
            <div key={f.title} style={{ background: '#fff', borderRadius: '16px', padding: '24px', boxShadow: '0 2px 12px rgba(0,0,0,0.06)' }}>
              <div style={{ fontSize: '32px', marginBottom: '12px' }}>{f.icon}</div>
              <div style={{ fontWeight: '800', fontSize: '15px', color: '#1a3a5c', marginBottom: '8px' }}>{f.title}</div>
              <div style={{ fontSize: '13px', color: '#64748b', lineHeight: '1.6' }}>{f.text}</div>
            </div>
          ))}
        </div>
      </div>

      {/* יתרון הקליניקה */}
      <div style={{ padding: '24px 24px 0', maxWidth: '860px', margin: '0 auto' }}>
        <div style={{ background: 'linear-gradient(135deg, #1a3a5c, #1e4a7a)', borderRadius: '20px', padding: '32px', color: '#fff' }}>
          <div style={{ fontSize: '22px', fontWeight: '800', marginBottom: '12px' }}>🏥 למה לעשות זאת בקליניקת פיזיותרפיה ולא בחנות?</div>
          <div style={{ fontSize: '14px', color: 'rgba(255,255,255,0.85)', lineHeight: '1.8', marginBottom: '20px' }}>
            בחנות מדרסים מקבלים סריקה — ותו לא. בקליניקת יואב אבני, הסריקה היא נקודת התחלה. יואב מבצע בדיקה פיזיותרפיסטית מלאה: בודק את הברך, הירך, הגב התחתון ואת הדפוס הביומכני כולו. כך המדרס מותאם לא רק לרגל — אלא לגוף כולו.
          </div>
          <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '10px' }}>
            {[
              'בדיקה ביומכנית מלאה לפני הסריקה',
              'התאמה לדפוס הליכה אישי',
              'מעקב אחרי קבלת המדרס',
              'ייעוץ לגבי הנעלה נכונה',
              'שילוב עם טיפול פיזיותרפיה במידת הצורך',
              'סיוע בהגשת בקשת החזר לקופ"ח / ביטוח',
            ].map(item => (
              <div key={item} style={{ display: 'flex', gap: '8px', alignItems: 'center', fontSize: '13px' }}>
                <span style={{ color: '#3eb8e5', fontWeight: '700', flexShrink: 0 }}>✓</span> {item}
              </div>
            ))}
          </div>
        </div>
      </div>

      {/* קהלי יעד */}
      <div style={{ padding: '40px 24px', maxWidth: '860px', margin: '0 auto' }}>
        <h2 style={{ fontSize: '24px', fontWeight: '800', color: '#1a3a5c', marginBottom: '8px', textAlign: 'center' }}>מי צריך מדרס בהתאמה אישית?</h2>
        <p style={{ fontSize: '13px', color: '#94a3b8', textAlign: 'center', marginBottom: '24px' }}>מחקרים מראים כי כ-75% מהאוכלוסייה סובלים מבעיה ביומכנית בכף הרגל שמשפיעה על שאר הגוף</p>
        <div style={{ display: 'grid', gridTemplateColumns: 'repeat(4,1fr)', gap: '12px' }}>
          {[
            { icon: '🏃', title: 'ספורטאים ורצים', text: 'מניעת פציעות חוזרות ושיפור ביצועים' },
            { icon: '🪖', title: 'חיילים', text: 'הפחתת עומס על הרגליים בפעילות מבצעית ממושכת' },
            { icon: '👨‍⚕️', title: 'עובדי בריאות', text: 'עמידה ממושכת — אחיות, רופאים, פיזיותרפיסטים' },
            { icon: '👷', title: 'עובדי כפיים', text: 'עומס ממושך על כפות הרגליים במהלך יום עבודה' },
            { icon: '🦴', title: 'כאבי עקב ודורבן', text: 'הפחתת לחץ ממוקד על נקודות הכאב' },
            { icon: '🦵', title: 'כאבי ברך וגב', text: 'תיקון ביומכני שמפחית עומס על המפרקים' },
            { icon: '👣', title: 'פלטפוס והולפוס', text: 'תמיכה מותאמת לקשת שטוחה או גבוהה' },
            { icon: '👴', title: 'גיל שלישי', text: 'שיפור יציבות ומניעת נפילות' },
          ].map(g => (
            <div key={g.title} style={{ background: '#fff', borderRadius: '12px', padding: '16px', boxShadow: '0 2px 8px rgba(0,0,0,0.06)', textAlign: 'center' }}>
              <div style={{ fontSize: '28px', marginBottom: '8px' }}>{g.icon}</div>
              <div style={{ fontWeight: '700', fontSize: '13px', color: '#1a3a5c', marginBottom: '4px' }}>{g.title}</div>
              <div style={{ fontSize: '11px', color: '#64748b', lineHeight: '1.5' }}>{g.text}</div>
            </div>
          ))}
        </div>
      </div>

      {/* החזרים */}
      <div style={{ padding: '0 24px 40px', maxWidth: '860px', margin: '0 auto' }}>
        <div style={{ background: '#f0fdf4', border: '1px solid #bbf7d0', borderRadius: '16px', padding: '24px' }}>
          <div style={{ fontWeight: '800', fontSize: '18px', color: '#065f46', marginBottom: '12px' }}>💰 החזרים מקופות חולים וביטוח</div>
          <div style={{ fontSize: '14px', color: '#374151', lineHeight: '1.8', marginBottom: '12px' }}>
            מדרסים אורטופדיים בהתאמה אישית זכאים להחזר כספי מקופות החולים ומפוליסות ביטוח פרטיות — בהצגת פניית רופא. יואב יסייע לך בתהליך.
          </div>
          <div style={{ display: 'grid', gridTemplateColumns: 'repeat(2,1fr)', gap: '8px' }}>
            {[
              'מכבי — החזר חלקי בצירוף פניית רופא',
              'כללית — החזר דרך מרכז שירותי בריאות',
              'מאוחדת — החזר חלקי בסל שירותים',
              'לאומית — החזר לפי תנאי הפוליסה',
              'ביטוח פרטי — בהתאם לפוליסה האישית',
              'פוליסת בריאות משלימה — כיסוי מלא/חלקי',
            ].map(item => (
              <div key={item} style={{ display: 'flex', gap: '8px', alignItems: 'center', fontSize: '13px', color: '#374151' }}>
                <span style={{ color: '#10b981', fontWeight: '700', flexShrink: 0 }}>✓</span> {item}
              </div>
            ))}
          </div>
        </div>
      </div>

      {/* מחיר */}
      <div style={{ padding: '0 24px 40px', maxWidth: '500px', margin: '0 auto', textAlign: 'center' }}>
        <div style={{ background: '#fff', borderRadius: '20px', padding: '32px', boxShadow: '0 4px 24px rgba(0,0,0,0.08)', border: '2px solid #3eb8e5' }}>
          <div style={{ fontSize: '12px', fontWeight: '700', color: '#3eb8e5', textTransform: 'uppercase', letterSpacing: '0.08em', marginBottom: '8px' }}>מדרס בהתאמה אישית</div>
          <div style={{ fontSize: '48px', fontWeight: '900', color: '#1a3a5c', marginBottom: '4px' }}>₪1,500</div>
          <div style={{ fontSize: '13px', color: '#94a3b8', marginBottom: '24px' }}>תשלום חד פעמי | ניתן לפריסה</div>
          <div style={{ display: 'flex', flexDirection: 'column', gap: '10px', textAlign: 'right', marginBottom: '24px' }}>
            {[
              'סריקת כף רגל עם Albert Pressure (5,184 חיישנים)',
              'סריקה סטטית + דינמית בהליכה',
              'בדיקה ביומכנית עם יואב אבני PT',
              'מדרס מותאם אישית ברמת הגימור הגבוהה ביותר',
              'הדרכה להנעלה נכונה',
              'מעקב חודש אחרי קבלת המדרס',
              'סיוע בהגשת בקשת החזר לקופ"ח / ביטוח',
            ].map((item, i) => (
              <div key={i} style={{ display: 'flex', gap: '10px', alignItems: 'center', fontSize: '13px', color: '#374151' }}>
                <span style={{ color: '#3eb8e5', fontWeight: '700', flexShrink: 0 }}>✓</span> {item}
              </div>
            ))}
          </div>
          <a href="#form" style={{ display: 'block', padding: '14px', background: '#1a3a5c', color: '#fff', borderRadius: '10px', fontSize: '16px', fontWeight: '800', textDecoration: 'none', boxShadow: '0 4px 14px rgba(26,58,92,0.3)' }}>
            לתיאום סריקה ←
          </a>
        </div>
      </div>

      {/* טופס */}
      <div id="form" style={{ padding: '0 24px 60px', maxWidth: '500px', margin: '0 auto' }}>
        <div style={{ background: '#fff', borderRadius: '20px', padding: '36px', boxShadow: '0 4px 24px rgba(0,0,0,0.08)' }}>
          {submitted ? (
            <div style={{ textAlign: 'center', padding: '20px' }}>
              <div style={{ fontSize: '56px', marginBottom: '16px' }}>🎉</div>
              <h3 style={{ fontSize: '22px', fontWeight: '800', color: '#1a3a5c', marginBottom: '8px' }}>קיבלנו את הפרטים!</h3>
              <p style={{ fontSize: '14px', color: '#64748b', lineHeight: '1.7' }}>יואב יחזור אליך בהקדם לתיאום מועד לסריקה.</p>
            </div>
          ) : (
            <>
              <h3 style={{ fontSize: '20px', fontWeight: '800', color: '#1a3a5c', marginBottom: '6px', textAlign: 'center' }}>השאר פרטים לתיאום סריקה</h3>
              <p style={{ fontSize: '13px', color: '#94a3b8', textAlign: 'center', marginBottom: '24px' }}>נחזור אליך תוך 24 שעות</p>
              <div style={{ display: 'flex', flexDirection: 'column', gap: '12px' }}>
                <div>
                  <label style={{ display: 'block', fontSize: '11px', fontWeight: '700', color: '#64748b', marginBottom: '5px', textTransform: 'uppercase' }}>שם מלא *</label>
                  <input value={form.name} onChange={e => set('name', e.target.value)} placeholder="ישראל כהן"
                    style={{ width: '100%', padding: '11px 14px', border: '1.5px solid #e2e8f0', borderRadius: '10px', fontSize: '14px', outline: 'none', fontFamily: 'Heebo, sans-serif' }} />
                </div>
                <div>
                  <label style={{ display: 'block', fontSize: '11px', fontWeight: '700', color: '#64748b', marginBottom: '5px', textTransform: 'uppercase' }}>טלפון *</label>
                  <input value={form.phone} onChange={e => set('phone', e.target.value)} placeholder="050-0000000"
                    style={{ width: '100%', padding: '11px 14px', border: '1.5px solid #e2e8f0', borderRadius: '10px', fontSize: '14px', outline: 'none', fontFamily: 'Heebo, sans-serif', direction: 'ltr', textAlign: 'right' }} />
                </div>
                <div>
                  <label style={{ display: 'block', fontSize: '11px', fontWeight: '700', color: '#64748b', marginBottom: '5px', textTransform: 'uppercase' }}>מה מטריד אותך?</label>
                  <textarea value={form.complaint} onChange={e => set('complaint', e.target.value)}
                    placeholder="כאב עקב, פלטפוס, כאבי ברך בריצה..."
                    style={{ width: '100%', padding: '11px 14px', border: '1.5px solid #e2e8f0', borderRadius: '10px', fontSize: '13px', outline: 'none', fontFamily: 'Heebo, sans-serif', minHeight: '80px', resize: 'vertical' }} />
                </div>
                <button onClick={submit} disabled={saving} style={{
                  width: '100%', padding: '14px', background: saving ? '#94a3b8' : '#1a3a5c',
                  color: '#fff', border: 'none', borderRadius: '10px',
                  fontSize: '16px', fontWeight: '800', cursor: saving ? 'not-allowed' : 'pointer',
                  fontFamily: 'Heebo, sans-serif', marginTop: '4px',
                  boxShadow: '0 4px 14px rgba(26,58,92,0.3)',
                }}>
                  {saving ? '⏳ שולח...' : 'שלח פרטים ←'}
                </button>
                <p style={{ fontSize: '11px', color: '#94a3b8', textAlign: 'center', margin: 0 }}>יואב יחזור אליך תוך 24 שעות לתיאום מועד לסריקה</p>
              </div>
            </>
          )}
        </div>
      </div>

      {/* Footer */}
      <div style={{ background: '#1a3a5c', padding: '24px', textAlign: 'center' }}>
        <img src={LOGO} style={{ height: '40px', objectFit: 'contain', marginBottom: '8px', filter: 'brightness(0) invert(1)' }} alt="לוגו" />
        <div style={{ fontSize: '12px', color: 'rgba(255,255,255,0.5)', marginTop: '8px' }}>
          תרשיש 8, גילון · 054-5953889 · <a href="https://www.yoav-avni-clinic.com" style={{ color: '#3eb8e5' }}>yoav-avni-clinic.com</a>
        </div>
      </div>
    </div>
  )
}
